//! Runs the language-neutral VERS test suite from the `vers-spec` submodule.
//!
//! The test cases are generated by `build.rs` from `vers-spec/tests/*.json`.
//! Cases for versioning schemes that vers-rs does not implement yet, and cases
//! listed in `known_failures.txt`, are ignored; run them with
//! `cargo test --test vers_spec -- --ignored`.

mod support;

include!(concat!(env!("OUT_DIR"), "/vers_spec_tests.rs"));
